#' Subgroup Effects
#'
#' 
#' @param data .
#' @param outcome .
#' @param treat .
#' @param control .
#' @param armTreat .
#' @param subgroups .
#' @param covs .
#' @param block .
#' @param cluster .
#' @param method .
#' @param se .
#' @param adjust .
#' @param level .
#' @param plot .
#' @param showHelp .
#' @param showGuide .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$overall} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$eff} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$inter} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$subPlot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$overall$asDF}
#'
#' \code{as.data.frame(results$overall)}
#'
#' @export
exsub <- function(
    data,
    outcome,
    treat,
    control = "",
    armTreat = "",
    subgroups,
    covs,
    block,
    cluster,
    method = "diff",
    se = "auto",
    adjust = "holm",
    level = 95,
    plot = TRUE,
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("exsub requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(treat)) treat <- jmvcore::resolveQuo(jmvcore::enquo(treat))
    if ( ! missing(subgroups)) subgroups <- jmvcore::resolveQuo(jmvcore::enquo(subgroups))
    if ( ! missing(covs)) covs <- jmvcore::resolveQuo(jmvcore::enquo(covs))
    if ( ! missing(block)) block <- jmvcore::resolveQuo(jmvcore::enquo(block))
    if ( ! missing(cluster)) cluster <- jmvcore::resolveQuo(jmvcore::enquo(cluster))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(treat), treat, NULL),
            `if`( ! missing(subgroups), subgroups, NULL),
            `if`( ! missing(covs), covs, NULL),
            `if`( ! missing(block), block, NULL),
            `if`( ! missing(cluster), cluster, NULL))


    options <- exsubOptions$new(
        outcome = outcome,
        treat = treat,
        control = control,
        armTreat = armTreat,
        subgroups = subgroups,
        covs = covs,
        block = block,
        cluster = cluster,
        method = method,
        se = se,
        adjust = adjust,
        level = level,
        plot = plot,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- exsubClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

